/* ELF version script for libcipherbird_c (Linux/GNU ld / lld).
 * Export ONLY the C ABI (cipherbird_*); make every other symbol local, hiding
 * the statically-linked dependency symbols (liboqs, blst, …). Minimizes the
 * library's surface to exactly the intended boundary. */
CIPHERBIRD {
  global:
    cipherbird_*;
  local:
    *;
};
